cd /hyperagents && printf '%s\n' '--- root and status ---' && git status --short && find . -maxdepth 2 -type f | sort | head -120 && printf '%s\n' '--- meta_agent.py ---' && cat meta_agent.py && printf '%s\n' '--- prior generation metadata ---' && for f in /tmp/generate_source_s6/gen_{1,4,5,6,7}/metadata.json; do echo "=== $f"; cat "$f"; done && printf '%s\n' '--- prediction format/sample ---' && python - <<'PY'
import json
for p in ['/tmp/generate_source_s6/gen_5/arc_eval/predictions.json','/tmp/generate_source_s6/gen_6/arc_eval/predictions.json']:
 try:
  d=json.load(open(p)); print('\n',p,type(d).__name__,len(d)); print(json.dumps(d,indent=2)[:2200])
 except Exception as e: print(p,e)
PY
printf '%s\n' '--- generate loop invocation and archive handling ---' && grep -R "MetaAgent\|eval_path\|iterations_left" -n run_meta_agent.py meta_agent.py && printf '%s\n' '--- recent chat summaries ---' && for f in /tmp/generate_source_s6/gen_{5,6,7}/agent_output/meta_agent_chat_history.md; do echo "=== $f"; tail -45 "$f" 2>/dev/null; done

cd /hyperagents && for f in /tmp/generate_source_s6/gen_{initial,1,4,5,6,7}/arc_eval/report.json; do echo "### $f"; cat "$f"; done; for f in /tmp/generate_source_s6/gen_{initial,1,4,5,6,7}/arc_eval/predictions.json; do echo "### $f"; python - "$f" <<'PY'
import json,sys
p=json.load(open(sys.argv[1])); print(type(p).__name__)
if isinstance(p,dict):
 print('keys',list(p)[:15]);
 for k,v in list(p.items())[:2]: print(k,repr(v)[:1000])
elif isinstance(p,list):
 print('len',len(p));
 for v in p[:2]: print(repr(v)[:1200])
PY
done; echo '--- history clues ---'; for f in /tmp/generate_source_s6/gen_{1,4,5,6,7}/agent_output/meta_agent_chat_history.md; do echo "### $f"; sed -n '1,180p' "$f"; done; echo '--- git_utils ---'; sed -n '1,220p' utils/git_utils.py; echo '--- report+arc util ---'; cat domains/arc/README.md; sed -n '1,240p' domains/arc/utils.py
